contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Accept ETH when C forwards it in fallback
    receive() external payable {}

    function run(uint amount) public payable {
        // must have enough balance to forward 'amount' to c
        require(address(this).balance >= amount);

        // observe pre-call values
        uint beforePast = c.pastBlockTime();
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // perform the fallback call by sending to c with empty data
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant:
        // - If call reverted then it must be because amount != 10 ether OR block.timestamp <= beforePast.
        // - If call succeeded then amount == 10 ether AND afterPast > beforePast.
        // - Additionally, if call succeeded and block.number % 15 == 0 then all prior contract balance was transferred to this contract (so this balance increased by that prior contract balance and contract balance became 0). Otherwise, the contract balance increased by amount and this contract balance decreased by amount.

        bool condRevertExplained = reverted ? (amount != 10 ether || !(afterPast > beforePast)) : true;

        bool successImpliesAmountAndTime = !reverted ? (amount == 10 ether && afterPast > beforePast) : true;

        // Determine whether block.number % 15 == 0 at the time of execution. We cannot call block.number of C, but it's same as current block.number.
        bool payoutBlock = (block.number % 15) == 0;

        // If succeeded and payoutBlock, then c sent its entire balance to this contract. That means afterThis == beforeThis + beforeCbal and afterCbal == 0.
        bool payoutBalancesOk = (!reverted && payoutBlock) ? (afterThis == beforeThis + beforeCbal && afterCbal == 0) : true;

        // If succeeded and not payoutBlock, then c should have accepted the 10 ether: its balance increases by amount (which equals 10 ether) and this decreases by amount.
        bool normalBalancesOk = (!reverted && !payoutBlock) ? (afterCbal == beforeCbal + amount && afterThis == beforeThis - amount) : true;

        assert(condRevertExplained && successImpliesAmountAndTime && payoutBalancesOk && normalBalancesOk);
    }
}

