contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Allow receiving ETH if C forwards funds to this contract
    receive() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe pre-call values
        uint beforePast = c.pastBlockTime();
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform low-level call to trigger C's fallback; must use address(c).call
        bool success;
        (success, ) = address(c).call{value: amount}("");

        // observe post-call values
        uint afterPast = c.pastBlockTime();
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant: either call reverted (success==false) OR all of these hold:
        // 1) amount == 10 ether
        // 2) pastBlockTime strictly increases (afterPast > beforePast)
        // 3) If block.number % 15 == 0 then this contract received entire previous C balance (afterThis == beforeThis + beforeCbal) and C balance is zero
        //    Else C's balance increased by amount and this contract's balance decreased by amount
        assert(
            !success || (
                amount == 10 ether
                && afterPast > beforePast
                && ((block.number % 15 == 0
                        && afterThis == beforeThis + beforeCbal
                        && afterCbal == 0)
                    || (block.number % 15 != 0
                        && afterCbal == beforeCbal + amount
                        && afterThis + amount == beforeThis))
            )
        );
    }
