contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send `amount` wei to c via a call to C's fallback by using the contract's low-level call to address(c).
    // The public test function must perform all state-changing interactions as top-level statements on c when possible.
    // Here we only have access to c via its address for invoking the fallback; to satisfy the requirement that
    // state-changing calls on c are top-level, we use try/catch on a call to a view (which is allowed) and then
    // perform the low-level call as a plain statement. However, solidity does not provide a direct way to express
    // a top-level fallback invocation through the typed variable c, so we instead make a plain low-level call to
    // address(c) as a top-level statement. This still observes only c's public surface via getters afterwards.

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Perform low-level call to trigger fallback; must be a top-level statement
        bool ok;
        (ok, ) = address(c).call{value: amount}("");

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule: either the call reverted (ok == false), or if it succeeded and exactly 10 ether was sent,
        // then pastBlockTime was set to block.timestamp and is >= previous value, and the balance is either increased
        // by 10 ether (normal accept) or zero (when fallback transferred all funds out).
        assert(
            !ok || (
                amount == 10 ether &&
                afterPast == block.timestamp &&
                afterPast >= beforePast &&
                (afterBal == beforeBal + 10 ether || afterBal == 0)
            )
        );
    }

    receive() external payable {}
}

