                amount == 10 ether &&
                afterPast == block.timestamp &&
                afterPast >= beforePast &&
                (afterBal == beforeBal + 10 ether || afterBal == 0)
            )
        );
    }

    // Allow this test contract to receive ether so it can forward funds to c
