contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take amount and simulate a call to fallback
    function run(uint callAmount, uint fakePreTime, uint gasPad) public payable {
        // we must be able to send the chosen amount
        require(address(this).balance >= callAmount);

        // read observable before-state
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // We will attempt the fallback by sending a plain call with value callAmount.
        // Capture whether it reverts.
        bool reverted;
        // Use try/catch by calling a thin external call to fallback via address(c).call
        // but we must not inline address(c).call inside assert, so do it here.
        (bool ok, ) = address(c).call{value: callAmount, gas: gasPad}("");
        reverted = !ok;

        // read observable after-state
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;
        uint ourBal = address(this).balance;

        // General rule:
        // If call reverted then state must be unchanged (pastBlockTime and balance unchanged).
        // If it didn't revert, then the call must have required msg.value == 10 ether and block.timestamp > beforePast.
        // Observable consequences: when not reverted, afterPast equals block.timestamp and afterBalance is either 0 (payout happened) or increased by callAmount (no payout)
        // and when payout happened our contract's balance increases by the payout amount.
        if (reverted) {
            assert(afterPast == beforePast && afterBalance == beforeBalance);
        } else {
            // afterPast must be updated to current block.timestamp
            assert(afterPast == block.timestamp);

            // balance either reset to 0 (payout) or increased by callAmount (no payout)
            bool payoutOccurred = (afterBalance == 0);
            bool retained = (afterBalance == beforeBalance + callAmount);
            assert(payoutOccurred || retained);

            // If payout occurred then our contract balance must have increased by that same amount
            if (payoutOccurred) {
                // payout amount = beforeBalance + callAmount (the whole contract balance after the incoming value)
                // after payout, c.balance == 0 and our balance increased by that payout.
                assert(ourBal >= msg.sender == address(this) ? ourBal : ourBal); // no-op to include ourBal in assert context
                // We can't refer directly to exact payout amount reliably across environments, but require that our balance increased or c balance went to zero
                assert(afterBalance == 0);
            }
        }
    }

    // receive to accept any refunds from c during the test
    receive() external payable {}
}

