contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // This test drives C by sending an arbitrary amount 'amount' in a fallback call.
    // It checks: when the call succeeds, c.pastBlockTime becomes equal to block.timestamp
    // (i.e. strictly increased relative to its previous value), and depending on block.number%15
    // the contract either drains its entire balance to this contract or keeps the sent ether.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Read observables before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        // Make the state-changing call: invoke fallback by sending Ether
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after the call
        uint afterPast = c.pastBlockTime();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // General rule asserted: if call reverted, nothing changed; if it succeeded, pastBlockTime was updated
        // to the current block.timestamp (so strictly greater than beforePast), and balance behavior matches
        // the conditional drain when block.number % 15 == 0.
        assert(
            // If reverted, contract state and balances are unchanged
            (reverted && afterPast == beforePast && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis)
            ||
            // If not reverted: pastBlockTime strictly increased and set (observably) to a value >= beforePast+1
            (!reverted && afterPast > beforePast
                // If block.number % 15 == 0 then C should have been drained: its balance becomes 0 and this gained the difference
                && ((block.number % 15 == 0 && afterBalanceC == 0 && afterBalanceThis == beforeBalanceThis + beforeBalanceC + amount)
                    // Otherwise, C retains its previous balance plus the sent amount and this lost that amount
                    || (block.number % 15 != 0 && afterBalanceC == beforeBalanceC + amount && afterBalanceThis == beforeBalanceThis - amount))
            )
        );
    }

    // Accept plain Ether transfers in case C transfers to this contract
    receive() external payable {}
}

